select city, case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, case when sqft >= 14544 then 'high' when sqft >= 3618 then 'mid' else 'low' end as sqft_bucket, sort_array(collect_set(city)) as city_list, concat_ws(', ', sort_array(collect_set(region))) as region_values, sum(sqft) as total_sqft from stores where city != 'Singapore' and length(store_name) > 8 group by 1, 2, 3
